import { ActionDefinition } from '../../../Action'
import { BooleanColumn, StringColumn, DurationColumn } from '../../../../db'

export const waitForMessage = ActionDefinition({
    $id: '605d0ab8931012105cd18166448918db',
    name: 'Wait For Message',
    description:
        'Pause a flow until it receives a specific message from the flow API. Specify the string message that resumes running the flow, and optionally provide a time-out value to resume the flow if no message is received after a specific amount of time.',
    category: '{}',
    inputs: {
        message: StringColumn({
            label: 'Message',
            mandatory: true,
            isFullUTF8: true,
            maxLength: 255,
        }),
        enable_timeout: BooleanColumn({
            label: 'Enable timeout',
        }),
        timeout: DurationColumn({
            label: 'Timeout',
            columnType: 'glide_duration',
        }),
    },
    outputs: {
        payload: StringColumn({
            label: 'Payload',
            isFullUTF8: true,
            maxLength: 255,
        }),
    },
})
